syntax = "proto3";

package sb.vectors.complex;

enum Kind {
  KIND_UNSPECIFIED = 0;
  KIND_CARD        = 1;
  KIND_WIRE        = 2;
}

message Money {
  string currency     = 1;
  int64  amount_minor = 2;
}

message Item {
  string          sku   = 1;
  Money           price = 2;
  repeated string tags  = 3;
}

message ComplexRequest {
  string              id     = 1;
  repeated Item       items  = 2;
  map<string, string> labels = 3;
  map<string, Money>  totals = 4;
  Kind                kind   = 5;

  oneof target {
    string account = 7;
    Money  card    = 9;
  }

  optional int32 retries = 12;
}

message ComplexResponse {
  bool          ok    = 1;
  repeated Kind kinds = 2;
}

syntax = "proto3";

package sb.vectors.alias;

enum Status {
  option allow_alias = true;
  STATUS_UNSPECIFIED = 0;
  STATUS_OK          = 1;
  STATUS_SUCCESS     = 1;
  STATUS_FAILED      = 4;
}

message AliasRequest {
  Status status = 1;
}

message AliasResponse {
  bool ok = 1;
}

syntax = "proto3";

package sb.vectors.cyclic;

message Node {
  string        id       = 1;
  repeated Node children = 2;
  Branch        branch   = 3;
}

message Branch {
  Node head = 1;
}

message CyclicResponse {
  int32 depth = 1;
}

syntax = "proto3";

package sb.vectors.empty;

message EmptyRequest {}

message EmptyResponse {
